const telefoneMatch = $('Get por telefone').item.json;
const emailMatch = $json;
const original = $('planilha').item.json;

const telefoneFound = Object.keys(telefoneMatch).length > 0;
const emailFound = Object.keys(emailMatch).length > 0;

let emailFinal = original.email;

if (emailFound) {
  const mesmoLead = telefoneFound && emailMatch.telefone === telefoneMatch.telefone;
  if (!mesmoLead) {
    emailFinal = null; // email já pertence a outro lead, deixa em branco
  }
}

return {
  json: {
    nome: original.nome,
    telefone: original.telefone,
    cargo: original.cargo,
    email: emailFinal,
    empresa_nome: original.empresa_nome,
    etapa: original.etapa,
    existe_por_telefone: telefoneFound
  }
};

const aliases = {
  nome: ['nome', 'nome completo', 'contato', 'name', 'full name'],
  cargo: ['cargo', 'posicao', 'posição', 'titulo', 'título', 'role', 'job title'],
  email: ['email', 'e-mail', 'email profissional'],
  telefone: ['telefone', 'celular', 'whatsapp', 'phone', 'mobile'],
  linkedin_url: ['linkedin', 'linkedin url', 'perfil linkedin'],
  empresa_nome: ['empresa', 'company', 'razao social', 'razão social', 'organizacao', 'organização'],
  empresa_cnpj: ['cnpj'],
  empresa_site: ['site', 'website', 'url empresa'],
  empresa_setor: ['setor', 'industry', 'segmento'],
  empresa_tamanho: ['tamanho', 'porte', 'funcionarios', 'funcionários', 'company size'],
  empresa_descricao: ['descricao', 'descrição', 'sobre empresa', 'company description'],
  observacoes: ['observacoes', 'observações', 'notas', 'obs', 'notes']
};

function normalizarChave(chave) {
  return chave.toString().trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function encontrarCampo(row, aliasesCampo) {
  for (const chave of Object.keys(row)) {
    if (aliasesCampo.some(a => normalizarChave(a) === normalizarChave(chave))) {
      return row[chave];
    }
  }
  return null;
}

function normalizarTelefone(valor) {
  if (!valor) return null;
  // pega só o primeiro telefone se vier vários separados por / ; , |
  const primeiro = String(valor).split(/[\/;,|]/)[0];
  const digitos = primeiro.replace(/\D/g, '');
  return digitos.length >= 8 ? digitos : null;
}

const camposConhecidos = Object.keys(aliases);
const validos = [];
const descartados = [];

for (const item of items) {
  const row = item.json;
  const nome = encontrarCampo(row, aliases.nome);
  const telefone = normalizarTelefone(encontrarCampo(row, aliases.telefone));

  if (!nome || !String(nome).trim() || !telefone) {
    descartados.push({
      json: {
        _valido: false,
        motivo: !telefone ? 'telefone_invalido_ou_ausente' : 'nome_ausente',
        nome_identificado: nome ? String(nome).trim() : null,
        telefone_identificado: encontrarCampo(row, aliases.telefone) || null,
        linha_original: row
      }
    });
    continue;
  }

  // colunas não reconhecidas viram extras (dados_enriquecimento)
  const extras = {};
  for (const chave of Object.keys(row)) {
    const reconhecido = camposConhecidos.some(campo =>
      aliases[campo].some(a => normalizarChave(a) === normalizarChave(chave))
    );
    if (!reconhecido) extras[chave] = row[chave];
  }

  validos.push({
    json: {
      _valido: true,
      nome: String(nome).trim(),
      telefone,
      cargo: encontrarCampo(row, aliases.cargo) || null,
      email: encontrarCampo(row, aliases.email) || null,
      linkedin_url: encontrarCampo(row, aliases.linkedin_url) || null,
      empresa_nome: encontrarCampo(row, aliases.empresa_nome) || null,
      empresa_cnpj: encontrarCampo(row, aliases.empresa_cnpj) || null,
      empresa_site: encontrarCampo(row, aliases.empresa_site) || null,
      empresa_setor: encontrarCampo(row, aliases.empresa_setor) || null,
      empresa_tamanho: encontrarCampo(row, aliases.empresa_tamanho) || null,
      empresa_descricao: encontrarCampo(row, aliases.empresa_descricao) || null,
      observacoes: encontrarCampo(row, aliases.observacoes) || null,
     etapa: $('Tabela Chegando').item.json.etapa || 'novo',
      dados_enriquecimento: Object.keys(extras).length > 0 ? extras : null
    }
  });
}

return [...validos, ...descartados];

function sufixoTelefone(valor) {
  if (!valor) return null;
  const digitos = String(valor).replace(/\D/g, '');
  return digitos.length >= 8 ? digitos.slice(-8) : null;
}

const tabelaCompleta = $('Buscar Tabela Completa').all().map(i => i.json);

const mapaTelefone = {};
const mapaEmail = {};
for (const linha of tabelaCompleta) {
  const sufixo = sufixoTelefone(linha.telefone);
  if (sufixo) mapaTelefone[sufixo] = linha;
  if (linha.email) mapaEmail[linha.email] = linha;
}

function normalizarComparacao(valor) {
  return (valor === undefined || valor === null) ? '' : String(valor).trim();
}

const donoDoEmailNoLote = {};
const resultado = [];

for (const item of $('Válido?').all().filter(i => i.json._valido === true)) {
  const original = item.json;
  const sufixoOriginal = sufixoTelefone(original.telefone);
  const existente = sufixoOriginal ? mapaTelefone[sufixoOriginal] : null;
  const existePorTelefone = !!existente;

  let emailFinal = original.email ? original.email.trim() : original.email;

  if (emailFinal) {
    const donoNaTabela = mapaEmail[emailFinal];
    const ehDonoLegitimoNaTabela = existente && donoNaTabela && sufixoTelefone(donoNaTabela.telefone) === sufixoOriginal;
    if (donoNaTabela && !ehDonoLegitimoNaTabela) {
      emailFinal = null;
    }
  }

  if (emailFinal) {
    const donoNoLote = donoDoEmailNoLote[emailFinal];
    if (donoNoLote && donoNoLote !== original.telefone) {
      emailFinal = null;
    } else {
      donoDoEmailNoLote[emailFinal] = original.telefone;
    }
  }

  let precisaAtualizar = true;
  if (existePorTelefone) {
    precisaAtualizar =
      normalizarComparacao(existente.nome) !== normalizarComparacao(original.nome) ||
      normalizarComparacao(existente.cargo) !== normalizarComparacao(original.cargo) ||
      normalizarComparacao(existente.email) !== normalizarComparacao(emailFinal) ||
      normalizarComparacao(existente.empresa_nome) !== normalizarComparacao(original.empresa_nome) ||
      normalizarComparacao(existente.etapa) !== normalizarComparacao(original.etapa);
  }

  resultado.push({
    json: {
      nome: original.nome,
      telefone: original.telefone,
      cargo: original.cargo,
      email: emailFinal,
      empresa_nome: original.empresa_nome,
      etapa: original.etapa,
      existe_por_telefone: existePorTelefone,
      precisa_atualizar: precisaAtualizar
    }
  });
}

// Colapsa duplicatas de telefone DENTRO do mesmo lote (mesma planilha)
// Mantém a ÚLTIMA ocorrência de cada telefone — assume que se a mesma
// pessoa aparece 2x na planilha, a linha mais abaixo é a mais atual/corrigida.
const porTelefone = new Map();
for (const r of resultado) {
  const suf = sufixoTelefone(r.json.telefone);
  const chave = suf || r.json.telefone;
  porTelefone.set(chave, r);
}

return Array.from(porTelefone.values());

function contarNode(nome) {
  try {
    return $(nome).all().length;
  } catch (e) {
    return 0;
  }
}

function itensDeNode(nome) {
  try {
    return $(nome).all();
  } catch (e) {
    return [];
  }
}

const descartadosRaw = itensDeNode('Válido?').filter(i => i.json._valido === false);

const descartados = descartadosRaw.map(i => ({
  nome: i.json.nome_identificado || '(não identificado)',
  telefone: i.json.telefone_identificado || '(não identificado)',
  motivo: i.json.motivo === 'telefone_invalido_ou_ausente'
    ? 'Telefone ausente ou inválido'
    : 'Nome ausente'
}));

return [{
  json: {
    sucesso: true,
    resumo: {
      atualizados: contarNode('Atualizar Lead'),
      criados: contarNode('Criar Lead'),
      ignorados: descartados.length
    },
    leads_ignorados: descartados
  }
}];

